@page "/category/{CategoryName}"

@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@{
    var recipes = Recipes.GetRecipesByCategory(CategoryName ?? "");
}

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span class="text-warning">
                                    @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++)
                                    {
                                        <text>★</text>
                                    }
                                    @for (int i = (int)Math.Round(recipe.AverageRating); i < 5; i++)
                                    {
                                        <text>☆</text>
                                    }
                                </span>
                                <small class="text-muted ms-1">(@recipe.AverageRating / 5)</small>
                            }
                            else
                            {
                                <small class="text-muted">No ratings yet</small>
                            }
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Home</a>

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{RecipeId:int}"

@using RecipeShare.Services
@inject RecipeService Recipes

@{
    var recipe = Recipes.GetRecipe(RecipeId);
}

<PageTitle>@(recipe?.Title ?? "Recipe Not Found") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="category/@recipe.Category">@recipe.Category</a></p>
    <p class="lead">@recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card mb-4">
                <div class="card-header"><strong>🥘 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card mb-4">
                <div class="card-header"><strong>📋 Steps</strong></div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>

    <div class="card mt-2 mb-4">
        <div class="card-body">
            <h5>⭐ Rate this Recipe</h5>
            <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>

    <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }
}

@using RecipeShare.Services
@inject RecipeService Recipes

<div>
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hovered ? "hovered" : star <= _selected ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  role="button"
                  title="@star star(s)">
                @(star <= (_hovered > 0 ? _hovered : _selected) ? "★" : "☆")
            </span>
        }
    </span>

    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }

    @{
        var recipe = Recipes.GetRecipe(RecipeId);
    }
    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <small class="text-muted ms-2">
            Average: @recipe.AverageRating / 5 (@recipe.Ratings.Count ratings)
        </small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _selected;
    private int _hovered;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selected = stars;
        Recipes.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

.star-rating {
    font-size: 1.8rem;
    letter-spacing: 0.15rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star.selected {
    color: #ffc107;
}

.star.hovered {
    color: #ffdb4d;
}

